import{_ as t,o as e,c as a,a2 as n}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Judicial System and Adjudication Mechanism","description":"","frontmatter":{},"headers":[],"relativePath":"en/48-司法体系与裁决机制.md","filePath":"en/48-司法体系与裁决机制.md","lastUpdated":1789183869000}'),o={name:"en/48-司法体系与裁决机制.md"};function s(r,i,l,d,c,u){return e(),a("div",null,[...i[0]||(i[0]=[n('<h1 id="judicial-system-and-adjudication-mechanism" tabindex="-1">Judicial System and Adjudication Mechanism <a class="header-anchor" href="#judicial-system-and-adjudication-mechanism" aria-label="Permalink to &quot;Judicial System and Adjudication Mechanism&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Content</th></tr></thead><tbody><tr><td>Document No.</td><td>48</td></tr><tr><td>Module</td><td>Legal System and Governance Framework</td></tr><tr><td>Core Keywords</td><td>Symbiotic Court, Independent adjudication, Multi-race adjudication, Cultivation case adjudication, Alternative dispute resolution</td></tr></tbody></table><h2 id="i-overview-of-the-judicial-system" tabindex="-1">I. Overview of the Judicial System <a class="header-anchor" href="#i-overview-of-the-judicial-system" aria-label="Permalink to &quot;I. Overview of the Judicial System&quot;">​</a></h2><p>The judicial system of the Anchor Symbiotic Civilization is an important part of the &quot;separation and balance of the three powers.&quot; The Symbiotic Court exercises adjudicative power independently in accordance with the law, adjudicates disputes between all lives within the Hengyuan Universe, safeguards justice, and maintains the symbiotic order of the rule of law.</p><p>The judicial system follows the following basic principles:</p><table tabindex="0"><thead><tr><th>Principle</th><th>Connotation</th></tr></thead><tbody><tr><td>Independent Adjudication</td><td>The Court exercises adjudicative power independently according to the law; no organization or individual may interfere</td></tr><tr><td>Impartial Adjudication</td><td>Cases are adjudicated on the basis of facts and the law; equal protection of the lawful rights and interests of all parties</td></tr><tr><td>Public Trial</td><td>Adjudication activities are open to the public, except for cases involving state secrets, life privacy, and business secrets</td></tr><tr><td>Two-Trial Final</td><td>Cases are subject to a final-instance system of two trials; appeal may be filed once for cases of first instance</td></tr><tr><td>Protection of Litigation Rights</td><td>The parties have the right to litigation, defense, appeal, and application for retrial</td></tr><tr><td>Multi-Race Participation</td><td>Representatives of all races participate in adjudication, ensuring that adjudication is adapted to the physiological and cultural characteristics of all races</td></tr></tbody></table><h2 id="ii-structure-and-jurisdiction-of-the-courts" tabindex="-1">II. Structure and Jurisdiction of the Courts <a class="header-anchor" href="#ii-structure-and-jurisdiction-of-the-courts" aria-label="Permalink to &quot;II. Structure and Jurisdiction of the Courts&quot;">​</a></h2><p>The Symbiotic Court is divided into multiple levels, with corresponding jurisdiction divisions:</p><table tabindex="0"><thead><tr><th>Court Level</th><th>Name</th><th>Jurisdiction</th></tr></thead><tbody><tr><td>First instance</td><td>Community Court</td><td>Minor civil disputes, minor disputes between residents, labor disputes, consumer disputes</td></tr><tr><td>Second instance</td><td>Regional Court</td><td>Civil, commercial, cultivation, administrative cases of ordinary importance</td></tr><tr><td>Third instance</td><td>Supreme Symbiotic Court</td><td>Major and complex cases, constitutional cases, cross-plane cases, cases involving multiple races</td></tr><tr><td>Special</td><td>Cultivation Special Court</td><td>Cultivation cases: deviation of cultivation, energy rebound, law erosion, sect disputes, cultivation resource disputes</td></tr><tr><td>Special</td><td>Consciousness Domain Court</td><td>Cases involving the consciousness domain, spiritual pollution, information crimes</td></tr><tr><td>Special</td><td>Military Court</td><td>Cases of military personnel and military-related cultivation activities</td></tr></tbody></table><p>The Supreme Symbiotic Court also enjoys the functions of unifying legal interpretation, issuing judicial interpretations, and supervising lower courts.</p><h2 id="iii-adjudication-mechanism" tabindex="-1">III. Adjudication Mechanism <a class="header-anchor" href="#iii-adjudication-mechanism" aria-label="Permalink to &quot;III. Adjudication Mechanism&quot;">​</a></h2><h3 id="i-multi-race-adjudication-institution" tabindex="-1">(I) Multi-Race Adjudication Institution <a class="header-anchor" href="#i-multi-race-adjudication-institution" aria-label="Permalink to &quot;(I) Multi-Race Adjudication Institution&quot;">​</a></h3><p>For cases involving special races, a multi-race adjudication institution is implemented:</p><ol><li>Cases involving a single race shall include assessors of that race in the collegiate bench.</li><li>Cases involving multiple races shall include assessors from the involved races; the composition of the bench is determined according to the number and complexity of the involved races.</li><li>For cases involving special physiological characteristics (such as aquatic races, energy lives), special experts may be invited to participate in adjudication.</li><li>Evidence and factual issues involving racial customs are determined with reference to the customary laws of the relevant races.</li></ol><h3 id="ii-cultivation-case-adjudication" tabindex="-1">(II) Cultivation Case Adjudication <a class="header-anchor" href="#ii-cultivation-case-adjudication" aria-label="Permalink to &quot;(II) Cultivation Case Adjudication&quot;">​</a></h3><p>Cultivation cases have high technical characteristics; the adjudication mechanism for cultivation cases includes:</p><ol><li><strong>Cultivation Expert Assessors</strong>: Cases involving professional issues such as deviation of cultivation, energy rebound, and law erosion shall have cultivation experts participate as assessors.</li><li><strong>Realm Evidence Determination</strong>: The determination of a cultivator&#39;s realm and strength is based on standard testing and appraisal institutions.</li><li><strong>Cultivation Law Application</strong>: The adjudication of cultivation cases shall apply cultivation laws and techniques, combining legal provisions with cultivation common sense.</li><li><strong>Special Execution</strong>: The execution of judgments in cultivation cases may use means such as energy restrictions and spiritual prohibitions.</li></ol><h3 id="iii-mediation-institution" tabindex="-1">(III) Mediation Institution <a class="header-anchor" href="#iii-mediation-institution" aria-label="Permalink to &quot;(III) Mediation Institution&quot;">​</a></h3><p>The Court promotes the mediation institution, encouraging the parties to resolve disputes through mediation:</p><ul><li><strong>Pre-litigation Mediation</strong>: For minor disputes, mediation is encouraged before litigation.</li><li><strong>Court Mediation</strong>: During the trial process, with the consent of the parties, the Court may conduct mediation.</li><li><strong>Mediation with Racial Characteristics</strong>: Mediation respects the customs and habits of all races; racial elders or ethnic representatives may participate in mediation.</li><li><strong>Effect of Mediation</strong>: A mediation agreement that is legally effective has binding force; failure to perform may be applied for enforcement.</li></ul><h3 id="iv-alternative-dispute-resolution" tabindex="-1">(IV) Alternative Dispute Resolution <a class="header-anchor" href="#iv-alternative-dispute-resolution" aria-label="Permalink to &quot;(IV) Alternative Dispute Resolution&quot;">​</a></h3><p>In addition to litigation, the following alternative dispute resolution methods are established:</p><table tabindex="0"><thead><tr><th>Method</th><th>Content</th></tr></thead><tbody><tr><td>Arbitration</td><td>Disputes that have agreed to arbitrate are resolved by the arbitration institution; the arbitration award is final</td></tr><tr><td>Expert Determination</td><td>Professional disputes may be determined by expert institutions</td></tr><tr><td>Symbiotic Consultation</td><td>Disputes between races or organizations are resolved through the Symbiotic Consultation Mechanism</td></tr><tr><td>Ancestor Meditation</td><td>For traditional disputes of special races, the mediation of racial elders may be adopted</td></tr></tbody></table><h2 id="iv-litigation-system" tabindex="-1">IV. Litigation System <a class="header-anchor" href="#iv-litigation-system" aria-label="Permalink to &quot;IV. Litigation System&quot;">​</a></h2><h3 id="i-plaintiff-qualification" tabindex="-1">(I) Plaintiff Qualification <a class="header-anchor" href="#i-plaintiff-qualification" aria-label="Permalink to &quot;(I) Plaintiff Qualification&quot;">​</a></h3><p>The following subjects have the right to file lawsuits:</p><ul><li>Natural lives and organizational subjects whose lawful rights and interests are harmed</li><li>The Symbiotic Prosecution Office may file public interest litigation for acts harming public interests</li><li>Legally designated public interest organizations may file public interest litigation within their scopes</li></ul><h3 id="ii-evidence-system" tabindex="-1">(II) Evidence System <a class="header-anchor" href="#ii-evidence-system" aria-label="Permalink to &quot;(II) Evidence System&quot;">​</a></h3><p>The evidence system of the Symbiotic Court includes:</p><ol><li><strong>Evidence Types</strong>: Physical evidence, documentary evidence, witness testimony, party statements, appraisal opinions, inspection records, consciousness domain evidence, etc.</li><li><strong>Burden of Proof</strong>: The plaintiff bears the burden of proof for the claims; the party asserting a favorable fact bears the burden of proof for that fact.</li><li><strong>Energy Evidence</strong>: Evidence extracted from the consciousness domain and energy traces must be extracted by legally authorized institutions to ensure legality and authenticity.</li><li><strong>Cross-Plane Evidence</strong>: Evidence involving multiple planes is mutually recognized and converted by the cross-plane judicial cooperation mechanism.</li></ol><h3 id="iii-execution-system" tabindex="-1">(III) Execution System <a class="header-anchor" href="#iii-execution-system" aria-label="Permalink to &quot;(III) Execution System&quot;">​</a></h3><p>Judgments and rulings that take legal effect must be performed. For those who refuse to perform, the Court may take the following enforcement measures:</p><ul><li>Freezing and transferring cultivation resources and properties</li><li>Energy restrictions and cultivation restrictions</li><li>Public announcement of dishonest conduct</li><li>Detention and other coercive measures (in serious circumstances)</li></ul><h2 id="v-judicial-supervision" tabindex="-1">V. Judicial Supervision <a class="header-anchor" href="#v-judicial-supervision" aria-label="Permalink to &quot;V. Judicial Supervision&quot;">​</a></h2><p>To ensure judicial fairness, the following supervision mechanisms are established:</p><ul><li><strong>Anchor Oversight Committee Supervision</strong>: The Anchor Oversight Committee supervises judicial activities in accordance with the law, ensuring the lawful operation of the judicial organs.</li><li><strong>Second-Trial and Retrial Supervision</strong>: The appellate system and retrial system correct erroneous first-instance judgments.</li><li><strong>Disciplinary Supervision</strong>: Judicial personnel who violate discipline are subject to disciplinary action.</li><li><strong>Social Supervision</strong>: The public supervises judicial activities through trial observation, public opinions, etc.</li></ul><h2 id="vi-judicial-cooperation-across-planes" tabindex="-1">VI. Judicial Cooperation Across Planes <a class="header-anchor" href="#vi-judicial-cooperation-across-planes" aria-label="Permalink to &quot;VI. Judicial Cooperation Across Planes&quot;">​</a></h2><p>For cross-plane cases, the judicial cooperation mechanism is established:</p><ol><li>Mutual recognition of judgments between planes.</li><li>Cross-plane service and evidence assistance.</li><li>Cross-plane criminal judicial cooperation.</li><li>Cross-plane enforcement assistance and sharing of dishonest conduct information.</li></ol><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>The <em>Judicial System and Adjudication Mechanism</em> is the final line of defense for the rule of law order of the Anchor Symbiotic Civilization. By establishing a multi-level court system, the multi-race adjudication institution, and the cultivation case adjudication mechanism, it ensures the fairness and authority of adjudication, and safeguards the lawful rights and interests of all lives, providing strong judicial guarantees for the joint advancement of all races.</p><h2 id="related-documents" tabindex="-1">Related Documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to &quot;Related Documents&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Symbiotic Constitution: General Principles)</li><li>49-治理框架与权力制衡 (Governance Framework and Balance of Powers)</li><li>44-医疗保障法 (Medical Security Law)</li><li>30-锚点议事会职能与议事规则 (Functions and Rules of Procedure of the Anchor Assembly)</li></ul>',43)])])}const p=t(o,[["render",s]]);export{m as __pageData,p as default};
